import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import saveSettings from 'flarum/admin/utils/saveSettings';
import { t } from '../../common/t';
const KEY = 'ernestdefoe-longshot.picks_leagues';

/**
 * Which of Picks' leagues to offer; none ticked means all of them. Saved as
 * soon as a box is ticked, like a permission.
 */
export default class LeaguePicker extends Component {
  saving = false;
  view() {
    const current = String(app.data.settings[KEY] || '').split(',').filter(Boolean);
    return m("div", {
      className: "Form-group"
    }, m("label", null, t('admin.settings.picks_leagues')), m("div", {
      className: "helpText"
    }, t('admin.settings.picks_leagues_help')), m("div", {
      className: "Longshot-leagues"
    }, Object.entries(this.attrs.leagues).map(([league, name]) => m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      disabled: this.saving,
      checked: current.includes(league),
      onchange: e => this.save(e.target.checked ? [...current, league] : current.filter(l => l !== league))
    }), name))));
  }
  save(leagues) {
    this.saving = true;
    saveSettings({
      [KEY]: leagues.join(',')
    }).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-longshot', 'admin/components/LeaguePicker', LeaguePicker);