import app from 'flarum/admin/app';
const base = () => `${app.forum.attribute('apiUrl')}/longshot/admin`;
export function adminGet(path, params = {}) {
  return app.request({
    method: 'GET',
    url: base() + path,
    params
  });
}
export function adminSend(method, path, body) {
  return app.request({
    method,
    url: base() + path,
    body
  });
}